window.kbPageData["views/entry/k-2ec71e3d81274aa8"] = {"key":"entry/k-2ec71e3d81274aa8","state":{"route":"entry/k-2ec71e3d81274aa8"},"node":{"id":"k-2ec71e3d81274aa8","mode":"k","title":"我国船舶和航空器内犯罪的刑法适用","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["我国刑法对中国船舶和航空器内犯罪的适用范围"],"qs":["国考 2024 行政执法 行测#12"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"在中华人民共和国船舶或者航空器内犯罪，适用我国刑法。这一规定也适用于处在我国领域外的我国船舶或航空器。","review":{"definition":"在中华人民共和国船舶或者航空器内犯罪，适用我国刑法。这一规定也适用于处在我国领域外的我国船舶或航空器。","explanation":"B项的国际列车虽从我国出发，但抢劫发生时列车已进入甲国。刑法第六条第二款列举的是船舶和航空器，国际列车不适用该款。题中行为人、被害人均为外国公民，按本题给出的事实，B符合题干所问的无管辖权情形。","references":[],"evidence":"凡在中华人民共和国船舶或者航空器内犯罪的，也适用本法","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 行政执法 行测#12":{"paper":"国考 2024 行政执法 行测","n":12,"mod":"常识判断","src":["dfddc59dc6e7d9da5d71.pdf",3],"asrc":["6493f3a6a55c38431852.pdf",4],"card":"09c18159a03e15fe052d6091","links":[{"id":"k-2ec71e3d81274aa8","role":"直接考查","why":"该交通工具管辖规则列明船舶和航空器，据此判断在境外行驶的国际列车是否落入这一规则。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-2ec71e3d81274aa8":[["国考 2024 行政执法 行测#12"]]}};
